# SpiralWaves/test_master.jl — EGD::sw-master-matrices (arXiv:2608.17003 Sec. II.C, main.tex:590-650, 718-737).
# Tests FIRST for `master.jl` + the GENERATED `master_derived.jl`: the relativistic master system
# dy/dr = C y + S, y = (δÛ, −iδû^r) (47) DERIVED in Julia by route R3 (EGD::jd-swap), the
# Newtonian-limit matrices (50b-g) and δu_φ (50a), the Landau corotation shift (62)-(63) and the
# corotation radius (61). GROUNDING:
#   (a) NUMERIC FIXTURE vs Mathematica: `fixtures/master_r1_fixture.jl` (generated by the emri-disk
#       script codes/cas/R1_numeric_fixture.wls from R1_notebook_expressions.m, sha256 3f0202a7…9fd9,
#       itself transcribed from load-paper-expressions.nb sha256 eabdb9ef…5af4): 40 points with EVERY
#       input an independent exact rational (ω_d complex) — the transcribed Julia must agree to 1e-13
#       (Float64) and 1e-35 (BigFloat 256) relative per entry. Since EGD::jd-swap this fixture gates
#       the R1 ORACLE (`fixtures/oracle/master_generated.jl`), NOT the build source: its points are
#       OFF-SHELL by construction (independent random inputs violate both W = 1/√(1−v²) and the
#       hydrostatic balance (11)) and the routes agree only on-shell — see the FINDING in
#       test_derived_equivalence.jl (e). The build source is gated on-shell by (f) below and by the
#       whole of test_derived_equivalence.jl.
#   (b) NEWTONIAN LIMIT: at χ = 0, a• = 1e4 and 1e5, h0 = 0.05 the relativistic `master_matrices`
#       with the Newtonian-limit source (ĥ_tt = −2Φ̂, all other components 0) agrees with
#       `master_matrices_newtonian` (50b-g, κ² = 4Ω² + 2rΩΩ', Σ ≡ ε) entrywise to O(M/a•), with the
#       relative difference shrinking ∝ 1/a• (ratio ≈ 10 between a• = 1e4 and 1e5).
#   (c) LANDAU SHIFT: ε(r_c) = εp Ω•(r_c) (63), Gaussian of width σε (vanishes 5σ away), r_c = a•
#       exactly for 𝔭 = 𝔮 = 0 (Ω = Ω_K), ω_d(r_c) = 0 in general (61).
#   (d) TYPE GENERICITY: BigFloat(256) path through DiscBackground{BigFloat}; @inferred.
#   (e) dΩ/dr (exact implicit differentiation of the hydrostatic-balance root; complex-step second
#       derivatives of the Spacetime potentials) vs BigFloat finite differences and vs the geodesic
#       closed form for 𝔭 = 𝔮 = 0.
#   (f) ON-SHELL END-TO-END: `master_matrices(DiscBackground, m, r; hmodes)` at the 50 physical points of
#       the R1-vs-R2 gate fixture (`fixtures/master_onshell_fixture.jl`, baked from the emri-disk
#       codes/cas/deriv-master-system-R2/master_fixture.json, 30 digits, R1 ≡ R2 exactly on-shell) with
#       the covariant analytic test profile — Float64 2e-9 (C; notebook-form cancellation, measured 7e-10) / 1e-12 (S),
#       BigFloat(256) 1e-27; Ω, Ω', v to 1e-14.
using Test
using LinearAlgebra
using AccretionDisc
using AccretionDisc.SpiralWaves
using AccretionDisc.SpiralWaves: MasterInputs, _master_entries, dOmega_dr

# the external-CAS oracles (notebook route R1 / Mathematica route R2), no longer in the build path
isdefined(@__MODULE__, :SpiralWavesOracle) ||
    include(joinpath(@__DIR__, "fixtures", "oracle", "oracle_module.jl"))
using AccretionDisc.Modes: disc_OmegaK

include(joinpath(@__DIR__, "fixtures", "master_r1_fixture.jl"))
include(joinpath(@__DIR__, "fixtures", "master_onshell_fixture.jl"))

# the covariant analytic test profile of the on-shell fixture (R1-vs-R2 gate, master_fixture.wls) and
# its exact r-derivatives: h_tt = exp(−((r−a)/(a/2))²), h_tφ = 0.3 r² Ω• h_tt, h_φφ = 0.7 r² h_tt,
# h_rr = 0.5 h_tt, h_zz = 0.2 h_tt
function _hmodes_onshell(r, a, ΩE)
    htt = exp(-((r - a) / (a / 2))^2)
    dhtt = htt * (-2 * (r - a) / (a / 2)^2)
    (htt = htt, htt_r = dhtt,
     htphi = 3 // 10 * r^2 * ΩE * htt, htphi_r = 3 // 10 * ΩE * (2r * htt + r^2 * dhtt),
     hphiphi = 7 // 10 * r^2 * htt, hphiphi_r = 7 // 10 * (2r * htt + r^2 * dhtt),
     hrr = htt / 2, hzz = htt / 5)
end

# parse a fixture scalar / (re, im) pair at precision T
_fx(::Type{T}, s::AbstractString) where {T<:Real} = parse(T, s)
_fx(::Type{T}, z::Tuple{<:AbstractString,<:AbstractString}) where {T<:Real} = Complex(parse(T, z[1]), parse(T, z[2]))

function _inputs_from_fixture(::Type{T}, pt) where {T<:Real}
    MasterInputs{T,Complex{T}}(
        pt.m,
        _fx(T, pt.nu), _fx(T, pt.nu_r), _fx(T, pt.psi), _fx(T, pt.psi_r), _fx(T, pt.mu), _fx(T, pt.mu_r),
        _fx(T, pt.omt_r), _fx(T, pt.W), _fx(T, pt.v), _fx(T, pt.Omega), _fx(T, pt.Omega_r),
        _fx(T, pt.omega_d),
        _fx(T, pt.p), _fx(T, pt.p_r), _fx(T, pt.eps), _fx(T, pt.eps_r), _fx(T, pt.Gamma1),
        _fx(T, pt.htt), _fx(T, pt.htt_r), _fx(T, pt.htphi), _fx(T, pt.htphi_r),
        _fx(T, pt.hphiphi), _fx(T, pt.hphiphi_r), _fx(T, pt.hrr), _fx(T, pt.hzz))
end

# Newtonian-limit source for the relativistic matrices: ĥ_tt = −2Φ̂ (g_tt = −(1 + 2Φ)), all other
# Fourier metric components 0 (R1 report §4: the ONLY choice that reproduces (50f-g))
_hmodes_newt(Φ, dΦ) = (htt = -2Φ, htt_r = -2dΦ, htphi = zero(Φ), htphi_r = zero(Φ),
                       hphiphi = zero(Φ), hphiphi_r = zero(Φ), hrr = zero(Φ), hzz = zero(Φ))

_relmax(A, B) = maximum(abs.(A .- B) ./ max.(abs.(B), eps(real(eltype(B)))))

@testset "SpiralWaves.master (arXiv:2608.17003 Sec. II.C)" begin

    @testset "(a) R1 ORACLE entries vs Mathematica fixture — Float64 1e-13" begin
        @test length(MASTER_R1_FIXTURE) == 40
        worst = 0.0
        for pt in MASTER_R1_FIXTURE
            inp = _inputs_from_fixture(Float64, pt)
            got = SpiralWavesOracle._master_entries(inp)
            ref = (_fx(Float64, pt.C00), _fx(Float64, pt.C01), _fx(Float64, pt.C10), _fx(Float64, pt.C11),
                   _fx(Float64, pt.S0), _fx(Float64, pt.S1))
            for k in 1:6
                @test got[k] isa ComplexF64
                rel = abs(got[k] - ref[k]) / max(abs(ref[k]), 1e-300)
                worst = max(worst, rel)
                @test rel ≤ 1e-13
            end
        end
        @info "R1 oracle fixture: worst Float64 relative deviation over 40 points × 6 entries = $worst"
        @test (@inferred SpiralWavesOracle._master_entries(_inputs_from_fixture(Float64, MASTER_R1_FIXTURE[1]))) isa NTuple{6,ComplexF64}
    end

    @testset "(a') R1 ORACLE entries vs Mathematica fixture — BigFloat(256) 1e-35" begin
        setprecision(BigFloat, 256) do
            worst = big"0"
            for pt in MASTER_R1_FIXTURE[1:8]          # 50-digit fixture literals; 8 points suffice
                inp = _inputs_from_fixture(BigFloat, pt)
                got = SpiralWavesOracle._master_entries(inp)
                ref = (_fx(BigFloat, pt.C00), _fx(BigFloat, pt.C01), _fx(BigFloat, pt.C10), _fx(BigFloat, pt.C11),
                       _fx(BigFloat, pt.S0), _fx(BigFloat, pt.S1))
                for k in 1:6
                    @test got[k] isa Complex{BigFloat}
                    rel = abs(got[k] - ref[k]) / abs(ref[k])
                    worst = max(worst, rel)
                    @test rel ≤ big"1e-35"
                end
            end
            @info "R1 oracle fixture: worst BigFloat(256) relative deviation over 8 points × 6 entries = $(Float64(worst))"
        end
    end

    @testset "(e) dΩ/dr: exact implicit derivative vs BigFloat FD and vs the geodesic closed form" begin
        # 𝔭 = 𝔮 = 0 ⇒ Ω = 1/(χ + r^{3/2}) exactly ⇒ Ω' = −(3/2) √r/(χ + r^{3/2})²
        for χ in (-0.9, 0.0, 0.5, 0.998), r in (6.5, 12.0, 40.0, 1e3)
            bg = DiscBackground(χ = χ, aEMRI = 15.0, h0 = 0.05)
            r < r_isco(bg) && continue
            dΩ = dOmega_dr(bg, r)
            @test abs(dΩ - (-(3 / 2) * sqrt(r) / (χ + r^(3 / 2))^2)) ≤ 1e-13 * abs(dΩ)
        end
        # pressure-supported profile: compare with a BigFloat(256) 5-point central difference
        setprecision(BigFloat, 256) do
            for (χ, 𝔭, 𝔮) in ((big"0.0", big"1.5", big"1.0"), (big"0.9", big"0.5", big"0.25"), (big"-0.6", big"2.0", big"0.5"))
                bg = DiscBackground{BigFloat}(χ = χ, aEMRI = big"15", h0 = big"0.1", 𝔭 = 𝔭, 𝔮 = 𝔮)
                for r in (big"9", big"15", big"60")
                    h = r * big"1e-12"
                    f(x) = Omega(bg, x)
                    fd = (-f(r + 2h) + 8f(r + h) - 8f(r - h) + f(r - 2h)) / (12h)     # error O(h⁴) ~ 1e-48
                    dΩ = dOmega_dr(bg, r)
                    @test dΩ isa BigFloat
                    @test abs(dΩ - fd) ≤ big"1e-40" * abs(fd)
                end
            end
        end
        # Float64 path agrees with the BigFloat path to a few eps
        bg64 = DiscBackground(χ = 0.7, aEMRI = 20.0, h0 = 0.08, 𝔭 = 1.0, 𝔮 = 0.5)
        bgbig = DiscBackground{BigFloat}(χ = 0.7, aEMRI = 20.0, h0 = 0.08, 𝔭 = 1.0, 𝔮 = 0.5)
        for r in (8.0, 20.0, 77.0)
            ref = setprecision(() -> dOmega_dr(bgbig, big(r)), BigFloat, 256)
            @test abs(dOmega_dr(bg64, r) - ref) ≤ 1e-13 * abs(ref)
        end
    end

    @testset "(c) corotation radius (61) and Landau shift (62)-(63)" begin
        for χ in (0.0, 0.9, -0.5), m in (1, 3, 20)
            bg = DiscBackground(χ = χ, aEMRI = 15.0, h0 = 0.05)               # 𝔭 = 𝔮 = 0 ⇒ Ω = Ω_K ⇒ r_c = a•
            rc = corotation_radius(bg, m)
            @test abs(rc - 15.0) ≤ 1e-12 * 15.0
            bgp = DiscBackground(χ = χ, aEMRI = 15.0, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
            rcp = corotation_radius(bgp, m)
            @test abs(omega_d(bgp, m, rcp)) ≤ 1e-12 * m * Omega_emri(bgp)
            @test rcp != 15.0                                                  # pressure shifts corotation
            @test r_isco(bgp) < rcp < 5 * bgp.aEMRI
            # ε(r_c) = εp Ω•(r_c); Gaussian width σε; 5σ away < e^{-12.5}
            ε_c = landau_shift(bgp, m, rcp; rc = rcp)
            @test ε_c ≈ bgp.εp * disc_OmegaK(bgp, rcp) rtol = 1e-14
            @test landau_shift(bgp, m, rcp + bgp.σε; rc = rcp) ≈ ε_c * exp(-1 / 2) rtol = 1e-14
            @test landau_shift(bgp, m, rcp - 2bgp.σε; rc = rcp) ≈ ε_c * exp(-2) rtol = 1e-14
            @test landau_shift(bgp, m, rcp + 5bgp.σε; rc = rcp) ≤ ε_c * exp(-12.5) * (1 + 1e-12)
            @test landau_shift(bgp, m, rcp) == ε_c                              # rc computed internally
            @test landau_shift(bgp, m, rcp) > 0
        end
        # the shift enters the matrices as ω_d → ω_d + iε(r): at r_c the un-shifted matrices are singular
        bg = DiscBackground(χ = 0.3, aEMRI = 15.0, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
        m = 3; rc = corotation_radius(bg, m)
        hm = _hmodes_newt(-1e-3, 1e-5)
        C, S = master_matrices(bg, m, rc; hmodes = hm, landau = true, rc = rc)
        @test all(isfinite, C) && all(isfinite, S)
        @test eltype(C) == ComplexF64 && size(C) == (2, 2) && length(S) == 2
        @test !all(isreal, C)                                                 # complex through iε
        # un-shifted at r_c: ω_d(r_c) = 0 (to roundoff; brent returns the exact root here) ⇒ the
        # 1/ω_d entries are singular (non-finite or ≫ the regularised ones)
        @test abs(omega_d(bg, m, rc)) ≤ 1e-15
        C0c, S0c = master_matrices(bg, m, rc; hmodes = hm, landau = false, rc = rc)
        @test !all(isfinite, C0c) || abs(C0c[1, 2]) > 1e3 * abs(C[1, 2])
        @test !all(isfinite, S0c) || abs(S0c[2]) > 1e3 * abs(S[2])
        # away from corotation the shift is exponentially small: landau on/off agree to ~e^{-12.5}
        r = rc + 5bg.σε
        C1, S1 = master_matrices(bg, m, r; hmodes = hm, landau = true, rc = rc)
        C0, S0 = master_matrices(bg, m, r; hmodes = hm, landau = false, rc = rc)
        @test _relmax(C1, C0) ≤ 1e-4 && _relmax(S1, S0) ≤ 1e-4
        @test all(isreal, C0) && all(isreal, S0)
        # landau=false equals the explicit ω_d evaluation
        @test C0 == master_matrices(bg, m, r; hmodes = hm, landau = false)[1]
    end

    @testset "(b) Newtonian limit: relativistic (ĥ_tt = −2Φ̂) vs (50b-g), O(M/a•) and ∝ 1/a•" begin
        m = 3; Φ, dΦ = -2.0e-3, 3.0e-7
        hm = _hmodes_newt(Φ, dΦ)
        devs = Dict{Float64,Float64}()
        for aEMRI in (1e4, 1e5)
            bg = DiscBackground(χ = 0.0, aEMRI = aEMRI, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
            worst = 0.0
            for x in (0.7, 1.1, 1.6)                                           # both sides of corotation (r_c ≈ a•)
                r = x * aEMRI
                Cr, Sr = master_matrices(bg, m, r; hmodes = hm, landau = false)
                Cn, Sn = master_matrices_newtonian(bg, m, r, Φ, dΦ; landau = false)
                @test all(isreal, Cr) && all(isreal, Cn)
                relC = abs.(Cr .- Cn) ./ abs.(Cn)
                relS = abs.(Sr .- Sn) ./ abs.(Sn)
                worst = max(worst, maximum(relC), maximum(relS))
                # O(M/a•) with an entry-dependent O(1–20) coefficient (measured, a• = 1e3…1e6: C01 at
                # r = 0.7a• is the largest, 20.9 M/a• — partial cancellation −ω_d + κ²/ω_d there; R1
                # report Part B: C01 ≈ 7 M/r at r = 1.1 r0); every other entry ≤ 7.2 M/a•
                @test maximum(relC) ≤ 25 / aEMRI
                @test maximum(relS) ≤ 25 / aEMRI
                @test relC[1, 1] ≤ 5 / aEMRI && relC[2, 1] ≤ 5 / aEMRI && relS[2] ≤ 5 / aEMRI
            end
            devs[aEMRI] = worst
            @info "Newtonian limit a•=$aEMRI: worst relative deviation = $worst (M/a• = $(1 / aEMRI))"
        end
        ratio = devs[1e4] / devs[1e5]
        @test 7 ≤ ratio ≤ 13                                                   # ∝ 1/a• (within 30 %; measured 10.00)
        @info "Newtonian limit: deviation ratio a•=1e4 / a•=1e5 = $ratio (expected 10 for ∝ 1/a•)"
        # Newtonian matrices: direct transcription check of (50b-g) at one point
        bg = DiscBackground(χ = 0.0, aEMRI = 1e4, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
        r = 1.3e4
        Cn, Sn = master_matrices_newtonian(bg, m, r, Φ, dΦ; landau = false)
        Ω = Omega(bg, r); dΩ = dOmega_dr(bg, r); κ2 = 4Ω^2 + 2r * Ω * dΩ
        p = pressure(bg, r); Σ = eps_profile(bg, r); Γ1 = gamma1(bg, r)
        dp = -(bg.𝔭 + bg.𝔮) * p / r; dΣ = -bg.𝔭 * Σ / r
        ωd = omega_d(bg, m, r)
        @test Cn[1, 1] ≈ 2m * Ω / (r * ωd) + dp / (Γ1 * p) - dΣ / Σ rtol = 1e-13
        @test Cn[1, 2] ≈ -ωd + (κ2 + dp * (-Σ * dp / (Γ1 * p) + dΣ) / Σ^2) / ωd rtol = 1e-13
        @test Cn[2, 1] ≈ -m^2 / (r^2 * ωd) + ωd * Σ / (Γ1 * p) rtol = 1e-13
        @test Cn[2, 2] ≈ -1 / r - m * κ2 / (2r * ωd * Ω) - dp / (Γ1 * p) rtol = 1e-13
        @test Sn[1] ≈ 2m * Φ * Ω / (r * ωd) - dΦ rtol = 1e-13
        @test Sn[2] ≈ -m^2 * Φ / (r^2 * ωd) rtol = 1e-13
        # (50a) δu_φ = m δÛ/(r ω_d) + m Φ̂/(r ω_d) − i δû^r κ²/(2 ω_d Ω) with y₂ = −i δû^r
        y = (0.3 + 0.1im, -0.2 + 0.05im)
        @test delta_u_phi_newtonian(bg, m, r, y, Φ; landau = false) ≈ m * (y[1] + Φ) / (r * ωd) + y[2] * κ2 / (2ωd * Ω) rtol = 1e-13
    end

    @testset "(f) ON-SHELL end-to-end: master_matrices(DiscBackground) vs the R1 ≡ R2 gate fixture (50 physical points)" begin
        # every input now comes from background.jl + Spacetime (Ω, v from (11), Ω' by dOmega_dr, potentials,
        # power laws) — the fixture values were produced by Mathematica from the same definitions (30 digits)
        @test length(MASTER_ONSHELL_FIXTURE) == 50
        worstΩ = 0.0; worstdΩ = 0.0; worstC = 0.0; worstS = 0.0
        for pt in MASTER_ONSHELL_FIXTURE
            bg = DiscBackground(χ = parse(Float64, pt.chi), aEMRI = parse(Float64, pt.aEMRI), h0 = parse(Float64, pt.h0),
                                𝔭 = parse(Float64, pt.pdisk), 𝔮 = parse(Float64, pt.qdisk))
            r = parse(Float64, pt.r); m = pt.m
            @test Omega_emri(bg) ≈ parse(Float64, pt.OmegaEMRI) rtol = 1e-14
            relΩ = abs(Omega(bg, r) - parse(Float64, pt.Omega)) / abs(parse(Float64, pt.Omega))
            reldΩ = abs(dOmega_dr(bg, r) - parse(Float64, pt.Omega_r)) / abs(parse(Float64, pt.Omega_r))
            worstΩ = max(worstΩ, relΩ); worstdΩ = max(worstdΩ, reldΩ)
            @test relΩ ≤ 1e-13
            @test reldΩ ≤ 1e-11                                            # Ω' by implicit differentiation (complex-step ψ'',ν'',ω̃'')
            @test abs(rotation_profile(bg, r).v - parse(Float64, pt.v)) ≤ 1e-13 * abs(parse(Float64, pt.v))
            hm = _hmodes_onshell(r, bg.aEMRI, Omega_emri(bg))
            C, S = master_matrices(bg, m, r; hmodes = hm, landau = false)
            refC = [_fx(Float64, pt.C00) _fx(Float64, pt.C01); _fx(Float64, pt.C10) _fx(Float64, pt.C11)]
            refS = [_fx(Float64, pt.S0), _fx(Float64, pt.S1)]
            rc = _relmax(C, refC); rs = _relmax(S, refS)
            worstC = max(worstC, rc); worstS = max(worstS, rs)
            # Float64 accuracy of the NOTEBOOK form of C00 degraded to ~1e-10 relative in the thin-disc
            # regime (small v, large r: the terms ∝ (ε+p)/(Γ1 p) ~ 1/h0² cancel to O(1/r); measured worst
            # 7.0e-10 at v = 0.038) [FINDING]. The DERIVED (route-R3) form of the same entries is better
            # conditioned there — measured worst 2.6e-12 over the same 50 points — so the bound is now
            # 1e-10 (38× margin) instead of the 2e-9 the notebook form needed [SOLID, EGD::jd-swap]
            @test rc ≤ 1e-10
            @test rs ≤ 1e-12
        end
        @info "on-shell fixture (Float64): worst rel dev Ω $worstΩ, Ω' $worstdΩ, C $worstC, S $worstS"
        @test worstΩ ≤ 1e-14 && worstdΩ ≤ 1e-14
        # BigFloat(256) path on 5 points: agreement at the 30-digit level of the fixture
        setprecision(BigFloat, 256) do
            worst = big"0"
            for pt in MASTER_ONSHELL_FIXTURE[1:10:50]
                bg = DiscBackground{BigFloat}(χ = parse(BigFloat, pt.chi), aEMRI = parse(BigFloat, pt.aEMRI), h0 = parse(BigFloat, pt.h0),
                                              𝔭 = parse(BigFloat, pt.pdisk), 𝔮 = parse(BigFloat, pt.qdisk))
                r = parse(BigFloat, pt.r); m = pt.m
                hm = _hmodes_onshell(r, bg.aEMRI, Omega_emri(bg))
                C, S = master_matrices(bg, m, r; hmodes = hm, landau = false)
                refC = [_fx(BigFloat, pt.C00) _fx(BigFloat, pt.C01); _fx(BigFloat, pt.C10) _fx(BigFloat, pt.C11)]
                refS = [_fx(BigFloat, pt.S0), _fx(BigFloat, pt.S1)]
                worst = max(worst, _relmax(C, refC), _relmax(S, refS))
                @test _relmax(C, refC) ≤ big"1e-27"
                @test _relmax(S, refS) ≤ big"1e-27"
                @test abs(dOmega_dr(bg, r) - parse(BigFloat, pt.Omega_r)) ≤ big"1e-27" * abs(parse(BigFloat, pt.Omega_r))
            end
            @info "on-shell fixture (BigFloat 256, 5 points): worst rel dev = $(Float64(worst))"
        end
    end

    @testset "(d) type genericity: BigFloat(256) background path and inference" begin
        setprecision(BigFloat, 256) do
            bg = DiscBackground{BigFloat}(χ = 0.6, aEMRI = 15, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
            m = 4
            hm = _hmodes_newt(big"-1e-3", big"1e-5")
            rc = corotation_radius(bg, m)
            @test rc isa BigFloat
            @test abs(omega_d(bg, m, rc)) ≤ big"1e-60"
            r = big"17.5"
            C, S = master_matrices(bg, m, r; hmodes = hm, rc = rc)
            @test eltype(C) == Complex{BigFloat} && eltype(S) == Complex{BigFloat}
            @test all(isfinite, C) && all(isfinite, S)
            # Float64 evaluation of the same point agrees with the BigFloat one to ~1e-12 (generic algebra)
            bg64 = DiscBackground(χ = 0.6, aEMRI = 15.0, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
            C64, S64 = master_matrices(bg64, m, 17.5; hmodes = _hmodes_newt(-1e-3, 1e-5), rc = Float64(rc))
            @test _relmax(C64, ComplexF64.(C)) ≤ 1e-11
            @test _relmax(S64, ComplexF64.(S)) ≤ 1e-11
            Cn, Sn = master_matrices_newtonian(bg, m, r, big"-1e-3", big"1e-5"; rc = rc)
            @test eltype(Cn) == Complex{BigFloat}
            @test landau_shift(bg, m, r; rc = rc) isa BigFloat
        end
        bg = DiscBackground(χ = 0.6, aEMRI = 15.0, h0 = 0.05, 𝔭 = 1.5, 𝔮 = 1.0)
        hm = _hmodes_newt(-1e-3, 1e-5)
        @test (@inferred master_matrices(bg, 4, 17.5; hmodes = hm, rc = 15.2)) isa Tuple{Matrix{ComplexF64},Vector{ComplexF64}}
        @test (@inferred master_matrices_newtonian(bg, 4, 17.5, -1e-3, 1e-5; rc = 15.2)) isa Tuple{Matrix{ComplexF64},Vector{ComplexF64}}
        @test (@inferred landau_shift(bg, 4, 17.5; rc = 15.2)) isa Float64
        @test (@inferred dOmega_dr(bg, 17.5)) isa Float64
        @test (@inferred corotation_radius(bg, 4)) isa Float64
        @test (@inferred delta_u_phi_newtonian(bg, 4, 17.5, (0.1 + 0im, 0.2 + 0im), -1e-3; rc = 15.2)) isa ComplexF64
    end
end
